package com.lexorion.payroll.api;
import static com.lexorion.payroll.api.PayrollHistoryDtos.*;import com.lexorion.payroll.domain.PayrollLedgerEntryType;import com.lexorion.payroll.service.PayrollHistoryService;import java.time.LocalDate;import java.util.List;import org.springframework.format.annotation.DateTimeFormat;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/payroll/employees/{employeeCode}")@PreAuthorize("hasRole('ADMIN')")public class PayrollHistoryController{private final PayrollHistoryService service;public PayrollHistoryController(PayrollHistoryService s){service=s;}@GetMapping("/ledger")public List<LedgerEntryResponse>ledger(@PathVariable String employeeCode,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate fromDate,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate toDate,@RequestParam(required=false)String payRunKey,@RequestParam(required=false)PayrollLedgerEntryType type){return service.ledger(employeeCode,fromDate,toDate,payRunKey,type);}@GetMapping("/payslips")public List<PayslipResponse>payslips(@PathVariable String employeeCode){return service.payslips(employeeCode);}@GetMapping("/payslips/{payRunKey}")public PayslipResponse payslip(@PathVariable String employeeCode,@PathVariable String payRunKey){return service.payslip(employeeCode,payRunKey);}}
